solution.code:
const express = require("express");
const app = express();

app.get("/bad", () => {
  throw new Error("dữ liệu sai");
});

app.use((err, req, res, next) => {
  res.status(400).json({ error: err.message });
});

app.inject("/bad").then((r) => console.log(r.statusCode, r.body));
